    filePath = path.join(__dirname, 'src/weather-card.js');
  } else if (req.url === '/data/sample.json') {
    filePath = path.join(__dirname, 'data/sample.json');
  } else if (req.url === '/src/') {
    res.writeHead(404);
    res.end('Not Found');
    return;
  } else {
    res.writeHead(404);
    res.end('Not Found');
    return;
  }

  sendFile(req, res, filePath);
});

server.listen(PORT, () => {
